INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Jahitan safety stitch tidak terbentuk dengan benar', 'Jahitan tidak rapat, tidak seimbang, atau kombinasi obras dan chainstitch tidak terbentuk sempurna.', 'Threading 5 benang tidak benar, tegangan benang tidak seimbang, atau penyetelan looper dan jarum kurang tepat.', 'Periksa jalur threading, sesuaikan tegangan masing-masing benang, dan periksa penyetelan jarum serta looper.', 'Matikan mesin dan putuskan sumber listrik sebelum melakukan penyetelan atau pemeriksaan area jarum dan looper.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Benang salah satu jarum sering putus', 'Salah satu dari tiga benang jarum sering putus saat proses menjahit.', 'Jarum rusak atau bengkok, ukuran jarum tidak sesuai, jalur benang terhambat, atau tegangan benang terlalu tinggi.', 'Ganti jarum yang rusak, pastikan pemasangan benar, periksa jalur benang, dan sesuaikan tegangan benang.', 'Matikan mesin sebelum mengganti jarum atau memeriksa jalur benang.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Benang looper atau chain looper sering putus', 'Benang looper atau chain looper putus berulang selama menjahit.', 'Threading looper tidak benar, tegangan terlalu tinggi, atau posisi looper tidak sesuai.', 'Periksa kembali jalur threading looper, sesuaikan tegangan, dan periksa posisi serta gerakan looper.', 'Matikan mesin sebelum membuka penutup dan memeriksa looper.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Jahitan salah satu jalur loncat atau tidak terbentuk', 'Salah satu jalur jahitan dari tiga jarum tidak terbentuk secara konsisten.', 'Jarum tidak sesuai atau pemasangannya salah, timing jarum-looper tidak tepat, atau threading tidak benar.', 'Periksa pemasangan ketiga jarum, kondisi jarum, jalur threading, dan penyetelan jarum-looper.', 'Matikan mesin sebelum memeriksa jarum dan mekanisme looper.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Tepi kain mengerut atau bergelombang', 'Tepi kain setelah dijahit terlihat mengerut, tertarik, atau bergelombang.', 'Differential feed tidak sesuai, tekanan presser foot terlalu tinggi, atau tegangan benang tidak seimbang.', 'Sesuaikan differential feed, periksa tekanan presser foot, dan seimbangkan tegangan benang.', 'Lakukan penyetelan saat mesin berhenti dan sumber listrik dimatikan.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Lebar obras atau posisi jahitan tidak sesuai', 'Lebar obras atau posisi kombinasi safety stitch bergeser dari hasil yang diharapkan.', 'Penyetelan posisi jarum, looper, pisau, atau pengaturan feeding tidak sesuai.', 'Periksa posisi jarum dan looper serta sesuaikan pengaturan feeding dan lebar jahitan sesuai kebutuhan.', 'Matikan mesin sebelum melakukan pemeriksaan pada jarum, looper, atau pisau.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Jarum patah atau posisi jarum tidak normal', 'Salah satu atau beberapa jarum patah, bengkok, atau tidak bergerak pada posisi yang benar.', 'Jarum bengkok, pemasangan tidak benar, ukuran jarum tidak sesuai, atau terjadi kontak dengan looper atau komponen lain.', 'Ganti jarum, pastikan ketiga jarum terpasang benar, dan periksa kemungkinan kontak jarum dengan looper.', 'Matikan mesin dan lepaskan sumber listrik sebelum mengganti jarum atau memeriksa mekanisme jarum.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (25, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terdengar kasar, bergerak tidak lancar, atau terdapat indikasi pelumasan yang tidak normal.', 'Pelumasan kurang, jalur pelumasan terganggu, atau terdapat bagian mekanis yang kotor atau mengalami keausan.', 'Periksa sistem pelumasan, bersihkan area yang diperlukan, dan lakukan pemeriksaan mekanis jika gerakan tetap tidak normal.', 'Matikan mesin sebelum melakukan pemeriksaan atau pembersihan bagian bergerak.', 'Data spesifikasi JUKI MO-6843S dan panduan pemeriksaan umum');
